package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import net.officefloor.hq.app.period.Periods;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

public class ApplyClaimStatus {
    public void apply(@Val ValidClaimStatus request, @Val Claim claim, Sheets sheets, People people,
            Rates rates, Periods periods, Settings settings, ClaimNumbering numbering, Out<ClaimNumber> number)
            throws ClaimStatusRefusedException {
        number.set(change(request, claim, sheets, people, rates, periods, settings, numbering));
    }

    /** Applies a status change to the claim by the rules of a single change, returning its number;
     *  throws, leaving the claim as it is, when the change is refused. Bulk settle uses it too. */
    static ClaimNumber change(ValidClaimStatus request, Claim claim, Sheets sheets, People people,
            Rates rates, Periods periods, Settings settings, ClaimNumbering numbering)
            throws ClaimStatusRefusedException {
        RoundingMode rounding = Rounding.of(claim, settings.policyDate(claim.getSheetId()));
        if (periods.isClosed(claim.getSheetId(), claim.getDate())) {
            throw new ClaimStatusRefusedException("No claim dated inside a closed period can change status");
        }
        boolean steward = Settings.STEWARD.equals(settings.role(claim.getSheetId(), request.user()));
        if (request.decision() != ValidClaimStatus.Decision.NONE) {
            // Only a steward approves or rejects, and only a PENDING claim.
            if (claim.getStatus() != ClaimStatus.PENDING) {
                throw new ClaimStatusRefusedException(claim.getStatus(), request.target());
            }
            if (!steward) {
                throw new ClaimStatusRefusedException("Only a steward can approve or reject a PENDING claim");
            }
        } else if (!claim.getStatus().canBecome(request.target())) {
            throw new ClaimStatusRefusedException(claim.getStatus(), request.target());
        }
        if (request.target() == ClaimStatus.SETTLED && claim.getOpenedBy() != null
                && claim.getOpenedBy().equals(request.user())) {
            // Four eyes: the user who opened a claim cannot settle (or approve) it.
            throw new ClaimStatusRefusedException("The user who opened a claim cannot settle it");
        }
        if (request.target() == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(claim.getSheetId()))) {
            throw new ClaimStatusRefusedException("A deferred claim cannot be settled until its deferred-until date");
        }
        ClaimStatus target = request.target();
        if (target == ClaimStatus.SETTLED && claim.getProofs() == 0) {
            // Above the proof threshold in force on the claim's date a claim needs a proof to be settled or approved,
            // judged on its due as shown (before the clerk limit is considered); a due of n/a is within any threshold.
            BigDecimal threshold = settings.proofThreshold(claim.getSheetId(), claim.getDate());
            BigDecimal due = shownDue(claim, sheets, people, rates, settings, rounding);
            if (threshold != null && due != null && due.compareTo(threshold) > 0) {
                throw new ClaimStatusRefusedException("A claim whose due is above the proof threshold needs a proof to be settled");
            }
        }
        if (target == ClaimStatus.SETTLED && request.decision() == ValidClaimStatus.Decision.NONE && !steward) {
            // A clerk settles only within the sheet's clerk limit, judged on the claim's due as shown;
            // a due of n/a is within any limit.
            BigDecimal limit = settings.clerkLimit(claim.getSheetId());
            BigDecimal due = shownDue(claim, sheets, people, rates, settings, rounding);
            if (limit != null && due != null && due.compareTo(limit) > 0) {
                // Above the clerk limit the claim awaits a steward's approval.
                target = ClaimStatus.PENDING;
            }
        }
        if (target == ClaimStatus.OPEN && request.decision() == ValidClaimStatus.Decision.NONE) {
            claim.setNumber(numbering.next(claim.getSheetId(), claim.getDate()));
            claim.setOpenedBy(request.user());
        }
        // A voided claim keeps its number; numbers are never reused.
        ClaimNumber number = new ClaimNumber(claim.getNumber());
        if (target == ClaimStatus.SETTLED) {
            // Settling (or approving) fixes the due: the figure a statement bound it to (never while PENDING), else its amount (raised to the floor)
            // at the rate in force on the claim's date, with its late charge as of today frozen in; with no
            // figure it stays live (n/a until a rate is set).
            String grade = people.find(claim.getSheetId(), claim.getPersonId()).gradeOn(claim.getDate());
            BigDecimal figure = claim.isBound() && claim.getStatedDue() != null ? claim.getStatedDue()
                    : Rates.due(claim.getAmount(), rates.find(claim.getSheetId(), grade, claim.getDate()),
                    settings.floor(claim.getSheetId(), claim.getDate()), rounding);
            claim.setSettledDue(LateCharge.withCharge(claim, figure, settings.latePct(claim.getSheetId(), claim.getDate()),
                    sheets.today(claim.getSheetId()), rounding));
        }
        // A rejected claim is OPEN again, so bound again by the last statement if it included it.
        claim.setStatus(target);
        return number;
    }

    /** The claim's due as shown: fixed (settled or bound), else its live figure with its late charge as of today; null for n/a. */
    private static BigDecimal shownDue(Claim claim, Sheets sheets, People people, Rates rates, Settings settings,
            RoundingMode rounding) {
        String grade = people.find(claim.getSheetId(), claim.getPersonId()).gradeOn(claim.getDate());
        BigDecimal fixed = ClaimResponse.fixedDue(claim);
        BigDecimal figure = fixed != null || claim.isBound() ? fixed
                : Rates.due(claim.getAmount(), rates.find(claim.getSheetId(), grade, claim.getDate()),
                settings.floor(claim.getSheetId(), claim.getDate()), rounding);
        return LateCharge.withCharge(claim, figure, settings.latePct(claim.getSheetId(), claim.getDate()),
                sheets.today(claim.getSheetId()), rounding);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Moves a DRAFT, OPEN or PENDING claim to another person on the sheet; only a steward moves a claim.
 * It keeps its number and date but loses any figure a statement bound it to: it is live again until
 * its new person's next statement.
 */
public class ApplyReassign {
    public void apply(@Val ReassignRequest request, @Val Claim claim, People people, Settings settings,
            Out<ClaimMove> move) throws ClaimStatusRefusedException {
        if (!Settings.STEWARD.equals(settings.role(claim.getSheetId(), request.user()))) {
            throw new ClaimStatusRefusedException("Only a steward can move a claim to another person");
        }
        ClaimStatus status = claim.getStatus();
        if (status != ClaimStatus.DRAFT && status != ClaimStatus.OPEN && status != ClaimStatus.PENDING) {
            throw new ClaimStatusRefusedException("A " + status + " claim cannot move to another person");
        }
        Person to = null;
        try {
            to = people.find(claim.getSheetId(), Long.parseLong(request.toPersonId()));
        } catch (NumberFormatException e) {
            // not an id this app assigned
        }
        if (to == null) {
            throw new ClaimStatusRefusedException("No such person to move the claim to");
        }
        if (to.getId() == claim.getPersonId()) {
            throw new ClaimStatusRefusedException("The claim is already that person's");
        }
        Person from = people.find(claim.getSheetId(), claim.getPersonId());
        claim.setPersonId(to.getId());
        claim.setStated(false);
        claim.setStatedDue(null);
        move.set(new ClaimMove(from, to));
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimResponse;
import net.officefloor.hq.app.claim.Claims;
import net.officefloor.hq.app.claim.LateCharge;
import net.officefloor.hq.app.claim.Rounding;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/** Closes a period, fixing its due-total as it is now: the dues as shown now of the claims dated in it that counted
 *  at the end of its last day (see {@link Person#countsAtEnd}), each with its late charge, and each person's share of it (a person's unbound OPEN claims dated within one of their holds count in none; a claim whose due is n/a adds nothing). */
public class ClosePeriod {
    public void close(@PathVariable("sheetId") String sheetId, @PathVariable("name") String name,
            @RequestBody ClosePeriodRequest request, Periods periods, People people, Claims claims, Rates rates,
            Settings settings, Sheets sheets, Audit audit, ObjectResponse<List<PeriodResponse>> response) throws InvalidPeriodException {
        PeriodResponse period = periods.lock(sheetId, name);
        if (period == null) {
            throw new InvalidPeriodException("No period named " + name + " is on the sheet");
        }
        if (period.closed()) {
            throw new InvalidPeriodException("The period " + name + " is already closed");
        }
        LocalDate from = LocalDate.parse(period.from());
        LocalDate to = LocalDate.parse(period.to());
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        LocalDate policyDate = settings.policyDate(sheetId);
        LocalDate today = sheets.today(sheetId);
        List<Claim> all = claims.list(sheetId);
        Map<Long, BigDecimal> personTotals = new LinkedHashMap<>();
        for (Person person : people.list(sheetId)) {
            BigDecimal personTotal = BigDecimal.ZERO.setScale(2);
            for (Claim claim : all) {
                if (claim.getPersonId() != person.getId() || !person.countsAtEnd(claim, to, today)
                        || claim.getDate().isBefore(from) || claim.getDate().isAfter(to)) {
                    continue;
                }
                RoundingMode rounding = Rounding.of(claim, policyDate);
                BigDecimal fixed = ClaimResponse.fixedDue(claim);
                BigDecimal figure = fixed != null || claim.isBound() ? fixed
                        : Rates.due(claim.getAmount(), rates.find(sheetId, person.gradeOn(claim.getDate()), claim.getDate()),
                        settings.floor(sheetId, claim.getDate()), rounding);
                if (figure != null) {
                    personTotal = personTotal.add(LateCharge.withCharge(claim, figure, settings.latePct(sheetId, claim.getDate()), today, rounding));
                }
            }
            personTotals.put(person.getId(), personTotal);
            total = total.add(personTotal);
        }
        periods.close(sheetId, name, total, personTotals);
        audit.recordOnCommit("PERIOD_CLOSED sheet=" + sheetId + " by=" + request.user()
                + " period=" + name + " total=" + total.toPlainString());
        response.send(periods.list(sheetId));
    }
}
package net.officefloor.hq.app.period;

import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/** Reopens a closed period, by a steward only: its fixed due-total is dropped, so it totals its
 *  claims' current figures again. */
public class ReopenPeriod {
    public void reopen(@PathVariable("sheetId") String sheetId, @PathVariable("name") String name,
            @RequestBody ClosePeriodRequest request, Periods periods, Settings settings, Audit audit,
            ObjectResponse<List<PeriodResponse>> response) throws InvalidPeriodException {
        if (!Settings.STEWARD.equals(settings.role(sheetId, request.user()))) {
            throw new InvalidPeriodException("Only a steward can reopen a period");
        }
        PeriodResponse period = periods.lock(sheetId, name);
        if (period == null) {
            throw new InvalidPeriodException("No period named " + name + " is on the sheet");
        }
        if (!period.closed()) {
            throw new InvalidPeriodException("The period " + name + " is not closed");
        }
        periods.reopen(sheetId, name);
        audit.recordOnCommit("PERIOD_REOPENED sheet=" + sheetId + " by=" + request.user() + " period=" + name);
        response.send(periods.list(sheetId));
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import net.officefloor.hq.app.period.Periods;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Re-settles a SETTLED claim; only a steward re-settles, and not a claim dated inside a closed period.
 * The settled due is frozen again at the figure the claim would have today as an open claim bound by no
 * statement: its amount (raised to the floor) at the rate of its person's grade in force on its date,
 * with its late charge as of today on top.
 */
public class ApplyResettle {
    public void apply(@Val ResettleRequest request, @Val Claim claim, Sheets sheets, People people, Rates rates,
            Periods periods, Settings settings, Out<ClaimResettle> resettle) throws ClaimStatusRefusedException {
        String sheetId = claim.getSheetId();
        if (!Settings.STEWARD.equals(settings.role(sheetId, request.user()))) {
            throw new ClaimStatusRefusedException("Only a steward can re-settle a claim");
        }
        if (claim.getStatus() != ClaimStatus.SETTLED) {
            throw new ClaimStatusRefusedException("Only a SETTLED claim can be re-settled");
        }
        if (periods.isClosed(sheetId, claim.getDate())) {
            throw new ClaimStatusRefusedException("No claim dated inside a closed period can be re-settled");
        }
        RoundingMode rounding = Rounding.of(claim, settings.policyDate(sheetId));
        String grade = people.find(sheetId, claim.getPersonId()).gradeOn(claim.getDate());
        BigDecimal figure = Rates.due(claim.getAmount(), rates.find(sheetId, grade, claim.getDate()),
                settings.floor(sheetId, claim.getDate()), rounding);
        BigDecimal due = figure == null ? null
                : figure.add(LateCharge.asOpen(claim, figure, settings.latePct(sheetId, claim.getDate()), sheets.today(sheetId), rounding));
        BigDecimal old = claim.getSettledDue();
        claim.setSettledDue(due);
        resettle.set(new ClaimResettle(old, due));
    }
}

