  });
  return (
    <>
      <form
        data-testid="settings-form"
        onSubmit={(e) => {
          e.preventDefault();
          submitSetting(() => {
            saveSetting.reset();
            // A dated setting is saved from its from-date (blank: the sheet's today).
            const save = (body: { key: string; value: string }) =>
              saveSetting.mutateAsync({ ...body, from: (froms[body.key] ?? '').trim() });
            const policy = policyDate.trim() !== '' || policyChosen.current;
            const numbering = numberingFrom.trim() !== '' || numberingChosen.current;
            const capped = cap.trim() !== '' || capChosen.current;
            const proofed = proofThreshold.trim() !== '' || proofChosen.current;
            const ownTerms = GRADES.filter((g) => (gradeTerms[g] ?? '').trim() !== '');
            if (terms.trim() !== '' || ownTerms.length > 0 || latePct.trim() !== '' || policy || numbering || capped || proofed) {
              const saves = [
                ...(limit.trim() !== '' ? [{ key: 'clerk-limit', value: limit.trim() }] : []),
                ...(floor.trim() !== '' ? [{ key: 'floor', value: floor.trim() }] : []),
                ...(terms.trim() !== '' ? [{ key: 'terms', value: terms.trim() }] : []),
                ...ownTerms.map((g) => ({ key: `terms-${g}`, value: gradeTerms[g].trim() })),
                ...(latePct.trim() !== '' ? [{ key: 'late-pct', value: latePct.trim() }] : []),
                ...(policy ? [{ key: 'policy-date', value: policyDate.trim() }] : []),
                ...(numbering ? [{ key: 'period-numbering-from', value: numberingFrom.trim() }] : []),
                ...(capped ? [{ key: 'cap', value: cap.trim() }] : []),
                ...(proofed ? [{ key: 'proof-threshold', value: proofThreshold.trim() }] : []),
              ];
              return saves.reduce<Promise<unknown>>((done, body) => done.then(() => save(body)), Promise.resolve());
            }
            if (floor.trim() === '') return save({ key: 'clerk-limit', value: limit.trim() });
            const saveFloor = () => save({ key: 'floor', value: floor.trim() });
            return limit.trim() === ''
              ? saveFloor()
              : save({ key: 'clerk-limit', value: limit.trim() }).then(saveFloor);
          });
        }}
      >
        Clerk limit: <span data-testid="setting-clerk-limit-current">{settings?.clerkLimit ?? ''}</span>{' '}
        <input
          data-testid="setting-clerk-limit"
          onFocus={unchoosePolicy}
          value={limit}
          placeholder="Clerk limit (blank: none)"
          onChange={(e) => {
            setLimit(e.target.value);
            saveSetting.reset();
          }}
        />{' '}
        {fromField('clerk-limit')}{' '}
        Floor: <span data-testid="setting-floor-current">{settings?.floor ?? ''}</span>{' '}
        <input
          data-testid="setting-floor"
          onFocus={unchoosePolicy}
          value={floor}
          placeholder="Floor (blank: unchanged)"
          onChange={(e) => {
            setFloor(e.target.value);
            saveSetting.reset();
          }}
        />{' '}
        {fromField('floor')}{' '}
        Terms (days): <span data-testid="setting-terms-current">{settings?.terms ?? ''}</span>{' '}
        <input
          data-testid="setting-terms"
          onFocus={unchoosePolicy}
          value={terms}
          placeholder="Terms in days (blank: unchanged)"
          onChange={(e) => {
            setTerms(e.target.value);
            saveSetting.reset();
          }}
        />{' '}
        {fromField('terms')}{' '}
        {GRADES.map((g) => (
          <span key={g}>
            Terms for grade {g} (days): <span data-testid={`setting-terms-${g}-current`}>{settings?.gradeTerms?.[g] ?? ''}</span>{' '}
            <input
              data-testid={`setting-terms-${g}`}
              onFocus={unchoosePolicy}
              value={gradeTerms[g] ?? ''}
              placeholder={`Grade ${g} terms in days (blank: unchanged)`}
              onChange={(e) => {
                const value = e.target.value;
                setGradeTerms((t) => ({ ...t, [g]: value }));
                saveSetting.reset();
              }}
            />{' '}
            {fromField(`terms-${g}`)}{' '}
          </span>
        ))}
        Late percent: <span data-testid="setting-late-pct-current">{settings?.latePct ?? ''}</span>{' '}
        <input
          data-testid="setting-late-pct"
          onFocus={unchoosePolicy}
          value={latePct}
          placeholder="Late percent (blank: unchanged)"
          onChange={(e) => {
            setLatePct(e.target.value);
            saveSetting.reset();
          }}
        />{' '}
        {fromField('late-pct')}{' '}
        Policy date: <span data-testid="setting-policy-date-current">{settings?.policyDate ?? ''}</span>{' '}
        <input
          data-testid="setting-policy-date"
          value={policyDate}
          placeholder="Policy date YYYY-MM-DD (blank: the sheet's today)"
          onFocus={() => {
            if (numberingFrom.trim() === '') numberingChosen.current = false;
            if (cap.trim() === '') capChosen.current = false;
            if (proofThreshold.trim() === '') proofChosen.current = false;
            policyChosen.current = true;
          }}
          onChange={(e) => {
            setPolicyDate(e.target.value);
            policyChosen.current = true;
            saveSetting.reset();
          }}
        />{' '}
        Period numbering from: <span data-testid="setting-period-numbering-from-current">{settings?.periodNumberingFrom ?? ''}</span>{' '}
        <input
          data-testid="setting-period-numbering-from"
          value={numberingFrom}
          placeholder="Period numbering from YYYY-MM-DD (blank: off)"
          onFocus={() => {
            if (policyDate.trim() === '') policyChosen.current = false;
            if (cap.trim() === '') capChosen.current = false;
            if (proofThreshold.trim() === '') proofChosen.current = false;
            numberingChosen.current = true;
          }}
          onChange={(e) => {
            setNumberingFrom(e.target.value);
            numberingChosen.current = true;
            saveSetting.reset();
          }}
        />{' '}
        Cap: <span data-testid="setting-cap-current">{settings?.cap ?? ''}</span>{' '}
        <input
          data-testid="setting-cap"
          value={cap}
          placeholder="Cap (blank: none)"
          onFocus={focusCap}
          onChange={(e) => {
            setCap(e.target.value);
            capChosen.current = true;
            saveSetting.reset();
          }}
        />{' '}
        {fromField('cap', focusCap)}{' '}
        Proof threshold: <span data-testid="setting-proof-threshold-current">{settings?.proofThreshold ?? ''}</span>{' '}
        <input
          data-testid="setting-proof-threshold"
          value={proofThreshold}
          placeholder="Proof threshold (blank: none)"
          onFocus={focusProof}
          onChange={(e) => {
            setProofThreshold(e.target.value);
            proofChosen.current = true;
            saveSetting.reset();
          }}
        />{' '}
        {fromField('proof-threshold', focusProof)}{' '}
        <button type="submit" data-testid="settings-save">Save settings</button>
        {saveSetting.isError && <span data-testid="settings-error" role="alert"> Could not save: the clerk limit must be an amount of 0.00 or more with at most two decimals, or blank for none; the floor must be an amount of 0.00 or more with at most two decimals; the terms (and a grade's terms) must be a whole number of days, 0 or more; the late percent must be a percent of 0.00 or more with at most two decimals; the policy date must be a date (YYYY-MM-DD), or blank for the sheet's today; the period numbering from must be a date (YYYY-MM-DD), or blank for off; the cap must be an amount of 0.00 or more with at most two decimals, or blank for none; the proof threshold must be an amount of 0.00 or more with at most two decimals, or blank for none; a from-date must be a date (YYYY-MM-DD), or blank for the sheet's today.</span>}
      </form>
      <table data-testid="role-list">
        <thead>
          <tr>
            <th>User</th>
            <th>Role</th>
          </tr>
        </thead>
        <tbody>
          {(settings?.roles ?? []).map((r) => (
            <tr key={r.user} data-testid={`role-row-${r.user}`}>
              <td data-testid="role-user">{r.user}</td>
              <td data-testid="role-value">{r.role}</td>
            </tr>
          ))}
        </tbody>
      </table>
      <form
        data-testid="role-form"
        onSubmit={(e) => {
          e.preventDefault();
          submitRole(() => {
            saveRole.reset();
            return saveRole.mutateAsync({ name: name.trim(), role: role.trim() });
          });
        }}
      >
        <input
          data-testid="role-form-user"
          value={name}
          placeholder="User name"
          onChange={(e) => {
            setName(e.target.value);
            saveRole.reset();
          }}
        />{' '}
        <input
          data-testid="role-form-role"
          value={role}
          placeholder="Role (clerk or steward)"
          onChange={(e) => {
            setRole(e.target.value);
            saveRole.reset();
          }}
        />{' '}
        <button type="submit" data-testid="role-form-submit">Set role</button>
        {saveRole.isError && <span data-testid="role-form-error" role="alert"> Could not set the role: it needs a user name and the role clerk or steward.</span>}
      </form>
    </>
  );
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { useSheetToday } from '../sheet/useSheetToday';

/** A role a user name holds on the sheet: clerk (any name not listed) or steward. */
export type Role = { user: string; role: string };

/** The sheet's settings, each dated one as in force on the sheet's today: the clerk limit with two decimals ("" for no limit), the floor with two
 *  decimals (a claim's live due is at least it), the terms in days (a new claim's due-by is its date
 *  plus them, unless its person's grade has its own terms), the late percent with two decimals (an overdue claim gains it of its figure for every
 *  full 30 days overdue), the policy date ("" for blank: the sheet's today), the period numbering from ("" for off: from it,
 *  a claim opened is numbered within its period), the roles set and each grade's own terms in days, by grade
 *  (a grade not listed uses the sheet's terms), the cap with two decimals ("" for none: a person's due-total is at most it) and the
 *  proof threshold with two decimals ("" for none: above the one in force on its date a claim needs a proof to be settled or approved). */
export type Settings = { clerkLimit: string; floor: string; terms: string; latePct: string; policyDate: string; periodNumberingFrom: string; roles: Role[]; gradeTerms: Record<string, string>; cap: string; dated: Record<string, Dated[]>; proofThreshold: string };

/** A value recorded for a dated setting (clerk-limit, floor, terms, terms-<grade>, late-pct, cap): the date
 *  it is in force from and the value ("" for none). The figures shown in Settings are those in force on the
 *  sheet's today; these are every value recorded, oldest first. */
export type Dated = { from: string; value: string };

/** The value of a dated setting in force on a date: the one with the latest from-date on or before it,
 *  else the sheet's starting value. */
export function inForce(settings: Settings | undefined, key: string, date: string, start: string): string {
  const before = (settings?.dated?.[key] ?? []).filter((d) => d.from <= date);
  const found = before[before.length - 1];
  return found === undefined || found.value === '' ? start : found.value;
}

/** The floor a sheet starts with, used until its settings have loaded. */
export const DEFAULT_FLOOR = '1.00';

export const settingsKey = (sheet: string) => ['sheet', sheet, 'settings'] as const;

export function useSettings(sheet: string): Settings | undefined {
  const { data } = useQuery({
    queryKey: settingsKey(sheet),
    queryFn: () => getJson<Settings>(`/api/sheets/${encodeURIComponent(sheet)}/settings`),
    enabled: sheet !== '',
  });
  return data;
}

/** The sheet's floor in force on a date (a claim's: its date). */
export function useFloor(sheet: string): (date: string) => string {
  const settings = useSettings(sheet);
  return (date) => inForce(settings, 'floor', date, DEFAULT_FLOOR);
}

/** The late percent a sheet starts with, used until its settings have loaded. */
export const DEFAULT_LATE_PCT = '0.00';

/** The sheet's late percent in force on a date (a claim's: its date). */
export function useLatePct(sheet: string): (date: string) => string {
  const settings = useSettings(sheet);
  return (date) => inForce(settings, 'late-pct', date, DEFAULT_LATE_PCT);
}

/** The sheet's policy date: the one set, or the sheet's today when it is blank. A claim dated before
 *  it rounds half up, one on or after it half to even. Undefined while loading. */
export function usePolicyDate(sheet: string): string | undefined {
  const set = useSettings(sheet)?.policyDate;
  const today = useSheetToday(sheet);
  return set ? set : today;
}

/** The sheet's cap in force on its today ("" for none): a person's due-total is at most it. */
export function useCap(sheet: string): string {
  return useSettings(sheet)?.cap ?? '';
}

